use super::*;

/// Scratch photon grids and splats are regenerated by the normal passes at each
/// sample. Both light sums, including the pre-compose beauty sum, survive samples.
#[derive(Clone)]
pub(crate) struct CausticCheckpoint {
    pub(crate) proof: Batch,
    planes: Vec<(wgpu::Buffer, Option<wgpu::Buffer>)>,
}

impl CausticCheckpoint {
    pub(crate) fn capture(
        scene: &GpuScene,
        target: &Target,
        caustics: &crate::caustics::State,
        start: u32,
    ) -> Self {
        let gpu = &scene.gpu;
        let proof = crate::native_completion::Recording::new();
        let mut encoder = gpu
            .device
            .create_command_encoder(&wgpu::CommandEncoderDescriptor {
                label: Some("Caustic flight checkpoint"),
            });
        let planes = (layout::resource::COLOR..=layout::resource::SHADOW_CATCHER)
            .map(|id| &target.buffers[&id])
            .chain(caustics.light_accumulations())
            .map(|buffer| {
                let copy = (start != 0).then(|| {
                    let copy = gpu.device.create_buffer(&wgpu::BufferDescriptor {
                        label: Some("Caustic checkpoint image"),
                        size: buffer.size(),
                        usage: wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::COPY_DST,
                        mapped_at_creation: false,
                    });
                    encoder.copy_buffer_to_buffer(buffer, 0, &copy, 0, buffer.size());
                    copy
                });
                (buffer.clone(), copy)
            })
            .collect();
        // Isolate pending camera/target uploads from the replayable sample writes.
        gpu.queue.submit([encoder.finish()]);
        Self {
            proof: proof.finish(),
            planes,
        }
    }

    pub(super) fn replay(
        &self,
        scene: &GpuScene,
        target: &Target,
        start: u32,
        end: u32,
        failed: &Batch,
        original: Box<dyn std::error::Error>,
    ) -> Result<()> {
        let begun = Instant::now();
        let deadline = begun + TIME_LIMIT;
        let gpu = &scene.gpu;
        let wait = || crate::query_guard::wait(scene, deadline);
        let mut attempts = 0;
        let mut reference = None;
        let result = (|| -> Result<()> {
            wait()?;
            self.proof.require_success("caustic checkpoint")?;
            let mut kind = failed.failure_kind();
            if kind == FailureKind::Unrecoverable {
                return Err("Retired caustic flight contains an unrecoverable command".into());
            }
            while attempts < MAX_RETRIES && Instant::now() < deadline {
                if kind == FailureKind::SubmissionsIgnored {
                    gpu.queue.renew()?;
                }
                attempts += 1;
                let recording = crate::native_completion::Recording::new();
                let mut encoder =
                    gpu.device
                        .create_command_encoder(&wgpu::CommandEncoderDescriptor {
                            label: Some("Restore caustic accumulations"),
                        });
                for (buffer, copy) in &self.planes {
                    if let Some(copy) = copy {
                        encoder.copy_buffer_to_buffer(copy, 0, buffer, 0, buffer.size());
                    } else {
                        encoder.clear_buffer(buffer, 0, None);
                    }
                }
                gpu.queue.submit([encoder.finish()]);
                let restore = recording.finish();
                wait()?;
                let completed = match restore.require_success("caustic checkpoint restoration") {
                    Err(error) => Err((restore.failure_kind(), error)),
                    Ok(()) => {
                        let batch = scene.dispatch_single_samples(target, start, end, None)?;
                        wait()?;
                        batch
                            .require_success("caustic flight replay")
                            .map_err(|e| (batch.failure_kind(), e))
                    }
                };
                if let Err((failure, error)) = completed {
                    if failure == FailureKind::Unrecoverable || attempts == MAX_RETRIES {
                        return Err(error);
                    }
                    kind = failure;
                    continue;
                }
                #[cfg(test)]
                if reference.is_some()
                    && std::mem::take(&mut gpu.recovery_test.lock().unwrap().corrupt_caustic_replay)
                {
                    gpu.queue.write_buffer(
                        &target.buffers[&layout::resource::COLOR],
                        0,
                        &1e6f32.to_ne_bytes(),
                    );
                }
                let images = self.read_accumulations(scene, deadline)?;
                if let Some(reference) = reference {
                    return verify_replay(reference, images, deadline);
                }
                reference = Some(images);
                kind = FailureKind::Retry;
            }
            Err("Caustic replay exceeded its bound".into())
        })();
        native_log!(
            "{}",
            serde_json::json!({"nativeFlightRecovery": {
                "flight": [start, end], "checkpoint": start, "retries": attempts,
                "reason": original.to_string(), "recovered": result.is_ok(), "caustics": true,
                "milliseconds": begun.elapsed().as_secs_f64()*1000.,
                "error": result.as_ref().err().map(ToString::to_string),
            }})
        );
        result.map_err(|e| {
            crate::status::fail(
                crate::Status::ContextFailed,
                format!("{original}; caustic checkpoint replay failed: {e}"),
            )
        })
    }

    fn read_accumulations(&self, scene: &GpuScene, deadline: Instant) -> Result<Vec<wgpu::Buffer>> {
        let gpu = &scene.gpu;
        let recording = crate::native_completion::Recording::new();
        let mut encoder = gpu
            .device
            .create_command_encoder(&wgpu::CommandEncoderDescriptor {
                label: Some("Verify caustic replay"),
            });
        let images: Vec<_> = self
            .planes
            .iter()
            .map(|(source, _)| {
                let buffer = gpu.device.create_buffer(&wgpu::BufferDescriptor {
                    label: Some("Caustic replay readback"),
                    size: source.size(),
                    usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
                    mapped_at_creation: false,
                });
                encoder.copy_buffer_to_buffer(source, 0, &buffer, 0, source.size());
                buffer
            })
            .collect();
        gpu.queue.submit([encoder.finish()]);
        let proof = recording.finish();
        let (tx, rx) = std::sync::mpsc::channel();
        for image in &images {
            let tx = tx.clone();
            image
                .slice(..)
                .map_async(wgpu::MapMode::Read, move |result| {
                    let _ = tx.send(result);
                });
        }
        crate::query_guard::wait(scene, deadline)?;
        proof.require_success("caustic verification readback")?;
        for _ in &images {
            rx.recv_timeout(deadline.saturating_duration_since(Instant::now()))??;
        }
        Ok(images)
    }
}

// Concurrent splats and photon gathers can differ in the last few bits of RGB.
// Require bit-exact guides, sample counts and coverage, including hidden light
// and pre-compose sums. Reject material disagreement instead of publishing one
// of two plausible images. This comparison is used only after an explicit error.
fn verify_replay(
    reference: Vec<wgpu::Buffer>,
    actual: Vec<wgpu::Buffer>,
    deadline: Instant,
) -> Result<()> {
    for (plane, (first, second)) in reference.iter().zip(&actual).enumerate() {
        let a = first.slice(..).get_mapped_range()?;
        let b = second.slice(..).get_mapped_range()?;
        for (left, right) in a.chunks(48 * 4096).zip(b.chunks(48 * 4096)) {
            if Instant::now() >= deadline {
                return Err("Caustic verification exceeded its deadline".into());
            }
            if left == right {
                continue;
            }
            let equal = bytemuck::cast_slice::<u8, u32>(left)
                .iter()
                .zip(bytemuck::cast_slice::<u8, u32>(right))
                .enumerate()
                .all(|(i, (&a, &b))| {
                    // ShadowCatcherAccumulation is three vec4s. Its two
                    // luminance moments share the radiance sum's rounding.
                    let radiance = match plane {
                        0 | 4 | 5 => i % 4 != 3,
                        3 => matches!(i % 12, 8 | 9),
                        _ => false,
                    };
                    a == b
                        || (radiance
                            && f32::from_bits(a).is_finite()
                            && f32::from_bits(b).is_finite()
                            && (a >> 31) == (b >> 31)
                            && a.abs_diff(b) <= 8)
                });
            if !equal {
                return Err(format!(
                    "Independent caustic replays disagree on accumulation plane {plane}"
                )
                .into());
            }
        }
    }
    Ok(())
}
